function classifyTabMessageTransportError(error, source = "runtime_last_error") {
  if (source === "sync_exception") return "SYNC_SEND_EXCEPTION";
  const message = String(error?.message || "").toLowerCase();
  if (message.includes("extension context invalidated")) return "CONTEXT_INVALIDATED";
  if (message.includes("receiving end does not exist")) return "NO_RECEIVER";
  if (message.includes("message port closed") || message.includes("message channel closed")) return "PORT_CLOSED";
  if (message.includes("no tab with id") || message.includes("tab was closed") || message.includes("frame was removed")) return "TAB_GONE";
  return "OTHER_TAB_MESSAGE_ERROR";
}

async function tabMessage(tabId, message) {
  return new Promise((resolve) => {
    let settled = false, deadline = null;
    const complete = (response) => {
      if (settled) return;
      settled = true;
      if (deadline !== null) clearTimeout(deadline);
      resolve(response);
    };
    // Reading identity has no side effects. A silent renderer cannot hold
    // popup/support/Finish validation forever. Mutating messages keep their
    // existing outcome protocol and never gain a deadline or retry here.
    if (message?.type === "OZ_GET_IDENTITY") deadline = setTimeout(() => complete({
      ok: false, code: "TAB_MESSAGE_TIMEOUT", transport_class: "RESPONSE_TIMEOUT"
    }), TAB_IDENTITY_RESPONSE_TIMEOUT_MS);
    try {
      chrome.tabs.sendMessage(tabId, message, (response) => {
        // Consume lastError even when this callback arrives after the deadline.
        const error = chrome.runtime.lastError;
        if (settled) return;
        if (error) return complete({
          ok: false,
          code: "TAB_MESSAGE_ERROR",
          transport_class: classifyTabMessageTransportError(error)
        });
        complete(response || { ok: false, code: "EMPTY_RESPONSE", error: "Пустой ответ вкладки." });
      });
    } catch (error) {
      complete({
        ok: false,
        code: "TAB_MESSAGE_ERROR",
        transport_class: classifyTabMessageTransportError(error, "sync_exception")
      });
    }
  });
}

